export const revenueSchemaStatements = [
  "CREATE TABLE IF NOT EXISTS revenue_calls (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, provider TEXT NOT NULL, title TEXT NOT NULL, account_name TEXT NOT NULL, duration_seconds INTEGER NOT NULL, consent_status TEXT NOT NULL, status TEXT NOT NULL, transcript_text TEXT NOT NULL, idempotency_key TEXT NOT NULL, created_at TEXT NOT NULL)",
  "CREATE TABLE IF NOT EXISTS revenue_assets (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, call_id TEXT NOT NULL, asset_type TEXT NOT NULL, title TEXT NOT NULL, department TEXT NOT NULL, status TEXT NOT NULL, content_json TEXT NOT NULL, created_at TEXT NOT NULL)",
  "CREATE TABLE IF NOT EXISTS knowledge_nodes (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, call_id TEXT NOT NULL, node_type TEXT NOT NULL, label TEXT NOT NULL, confidence REAL NOT NULL, evidence TEXT NOT NULL, created_at TEXT NOT NULL)",
  "CREATE TABLE IF NOT EXISTS knowledge_edges (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, call_id TEXT NOT NULL, source_id TEXT NOT NULL, target_id TEXT NOT NULL, relation TEXT NOT NULL, created_at TEXT NOT NULL)",
  "CREATE TABLE IF NOT EXISTS intelligence_signals (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, signal_type TEXT NOT NULL, severity TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, owner_department TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL)",
  "CREATE TABLE IF NOT EXISTS deletion_requests (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, requested_by TEXT NOT NULL, scope TEXT NOT NULL, target_id TEXT NOT NULL, status TEXT NOT NULL, delete_after TEXT NOT NULL, completed_at TEXT, created_at TEXT NOT NULL)",
  "CREATE TABLE IF NOT EXISTS connector_connections (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, provider TEXT NOT NULL, status TEXT NOT NULL, mode TEXT NOT NULL, scopes_json TEXT NOT NULL, last_synced_at TEXT, last_error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL)",
  "CREATE TABLE IF NOT EXISTS asset_reviews (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, asset_id TEXT NOT NULL, reviewer TEXT NOT NULL, decision TEXT NOT NULL, rationale TEXT NOT NULL, created_at TEXT NOT NULL)",
  "CREATE TABLE IF NOT EXISTS advisor_actions (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, signal_id TEXT, action_type TEXT NOT NULL, title TEXT NOT NULL, owner_department TEXT NOT NULL, status TEXT NOT NULL, requested_by TEXT NOT NULL, result_json TEXT NOT NULL, completed_at TEXT, created_at TEXT NOT NULL)",
  "CREATE TABLE IF NOT EXISTS revenue_audit_events (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, metadata_json TEXT NOT NULL, created_at TEXT NOT NULL)",
  "CREATE UNIQUE INDEX IF NOT EXISTS revenue_calls_idempotency_idx ON revenue_calls(organization_id, idempotency_key)",
  "CREATE INDEX IF NOT EXISTS revenue_calls_org_idx ON revenue_calls(organization_id, created_at)",
  "CREATE INDEX IF NOT EXISTS revenue_assets_call_idx ON revenue_assets(organization_id, call_id, created_at)",
  "CREATE INDEX IF NOT EXISTS knowledge_nodes_call_idx ON knowledge_nodes(organization_id, call_id, node_type)",
  "CREATE INDEX IF NOT EXISTS intelligence_signals_status_idx ON intelligence_signals(organization_id, status, created_at)",
  "CREATE INDEX IF NOT EXISTS deletion_requests_status_idx ON deletion_requests(organization_id, status, created_at)",
  "CREATE UNIQUE INDEX IF NOT EXISTS connector_connections_provider_idx ON connector_connections(organization_id, provider)",
  "CREATE INDEX IF NOT EXISTS asset_reviews_asset_idx ON asset_reviews(organization_id, asset_id, created_at)",
  "CREATE INDEX IF NOT EXISTS advisor_actions_status_idx ON advisor_actions(organization_id, status, created_at)",
  "CREATE INDEX IF NOT EXISTS revenue_audit_events_entity_idx ON revenue_audit_events(organization_id, entity_type, entity_id, created_at)",
];

function response(data, status = 200) {
  return new Response(JSON.stringify(data), { status, headers: { "content-type": "application/json" } });
}

const dnaWeights = { marketCoverage: .25, messagingConsistency: .2, behaviorReadiness: .2, evidenceFreshness: .15, closedLoopActivation: .1, governanceHealth: .1 };

export function calculateRevenueDna(input) {
  const callCount = Math.max(0, Number(input.callCount || 0));
  if (!callCount) return { status: "insufficient_evidence", overall: null, confidence: 0, components: null };
  const clamp = (value) => Math.max(0, Math.min(100, Math.round(value)));
  const expectedNodes = callCount * 6; const expectedAssets = callCount * 20; const expectedReadiness = callCount * 3;
  const driftPenalty = (input.signals || []).filter((signal) => signal.signal_type === "knowledge_drift").reduce((sum, signal) => sum + (signal.severity === "high" ? 18 : signal.severity === "medium" ? 9 : 4), 0);
  const components = {
    marketCoverage: clamp((Number(input.nodeCount || 0) / expectedNodes) * 60 + Math.min(40, callCount * 8)),
    messagingConsistency: clamp(100 - driftPenalty),
    behaviorReadiness: clamp((Number(input.approvedReadinessAssetCount ?? input.readinessAssetCount ?? 0) / expectedReadiness) * 100),
    evidenceFreshness: clamp((Number(input.recentCallCount || 0) / callCount) * 100),
    closedLoopActivation: clamp((Number(input.approvedAssetCount || 0) / expectedAssets) * 100),
    governanceHealth: clamp((Number(input.consentedCallCount || 0) / callCount) * 100),
  };
  const overall = Math.round(Object.entries(dnaWeights).reduce((sum, [key, weight]) => sum + components[key] * weight, 0));
  return { status: "complete", overall, confidence: clamp(40 + callCount * 12), components, weights: dnaWeights };
}

function redact(text) {
  return text.replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, "[EMAIL]").replace(/(?:\+?1[-.\s]?)?\(?\d{3}\)?[-.\s]?\d{3}[-.\s]?\d{4}/g, "[PHONE]");
}

function resolveOrganizationId(env) {
  return String(env.AUTHORIZED_ORGANIZATION_ID || "organization-default");
}

function resolveActor(request, env) {
  return String(request.headers.get("oai-authenticated-user-email") || env.AUTHORIZED_ACTOR_ID || "owner-demo").slice(0, 160);
}

export function validateAssetReview(input) {
  const decision = String(input?.decision || ""); const rationale = String(input?.rationale || "").trim().slice(0, 1000);
  if (!["approved", "changes_requested", "rejected"].includes(decision)) return { ok: false, code: "validation_failed" };
  if (decision !== "approved" && rationale.length < 8) return { ok: false, code: "rationale_required" };
  return { ok: true, decision, rationale: rationale || "Approved after evidence review." };
}

async function auditRevenueAction(env, organizationId, actor, action, entityType, entityId, metadata = {}) {
  await env.DB.prepare("INSERT INTO revenue_audit_events VALUES (?, ?, ?, ?, ?, ?, ?, ?)").bind(crypto.randomUUID(), organizationId, actor, action, entityType, entityId, JSON.stringify(metadata), new Date().toISOString()).run();
}

async function ensureRevenueOS(env, organizationId) {
  if (!env.DB) return false;
  await env.DB.batch(revenueSchemaStatements.map((sql) => env.DB.prepare(sql)));
  const count = await env.DB.prepare("SELECT COUNT(*) count FROM intelligence_signals WHERE organization_id = ?").bind(organizationId).first();
  if (!count?.count) {
    const now = new Date().toISOString();
    await env.DB.batch([
      env.DB.prepare("INSERT INTO intelligence_signals VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)").bind(crypto.randomUUID(), organizationId, "knowledge_drift", "high", "CRM replacement language is drifting", "Recent calls position Suadence as replacing CRM reporting, while approved messaging says it complements the CRM workflow.", "Enablement", "open", now),
      env.DB.prepare("INSERT INTO intelligence_signals VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)").bind(crypto.randomUUID(), organizationId, "content_gap", "medium", "No enterprise security talk track", "Security and data-retention questions appeared in 7 calls, but no approved talk track or battle card exists.", "Marketing", "open", now),
      env.DB.prepare("INSERT INTO intelligence_signals VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)").bind(crypto.randomUUID(), organizationId, "product_signal", "medium", "Administrative burden is rising", "Buyer concern about duplicate data entry increased 31% over the last 30 days.", "Product", "open", now),
    ]);
  }
  await env.DB.prepare("UPDATE revenue_assets SET status = 'review_required' WHERE organization_id = ? AND status = 'ready'").bind(organizationId).run();
  const connectorCount = await env.DB.prepare("SELECT COUNT(*) count FROM connector_connections WHERE organization_id = ?").bind(organizationId).first();
  if (!connectorCount?.count) {
    const now = new Date().toISOString(); const upload = connectorCatalog.find((connector) => connector.provider === "upload");
    await env.DB.prepare("INSERT INTO connector_connections VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)").bind(crypto.randomUUID(), organizationId, "upload", "connected", "native", JSON.stringify(upload.scopes), now, null, now, now).run();
  }
  return true;
}

function nodeBlueprints(callId, transcript) {
  const evidence = redact(transcript).replace(/\s+/g, " ").slice(0, 150);
  return [
    ["persona", "VP Sales Operations", .94],
    ["pain", "Forecast reconciliation", .92],
    ["impact", "Leadership distrust", .88],
    ["objection", "CRM already reports", .91],
    ["risk", "Administrative burden", .89],
    ["next_step", "Systems lead follow-up", .81],
  ].map(([type, label, confidence]) => ({ id: crypto.randomUUID(), callId, type, label, confidence, evidence }));
}

async function generateRevenueAssets(env, call) {
  const existing = await env.DB.prepare("SELECT COUNT(*) count FROM revenue_assets WHERE organization_id = ? AND call_id = ?").bind(call.organization_id, call.id).first();
  if (Number(existing?.count || 0) >= 20) {
    const rows = await env.DB.prepare("SELECT * FROM revenue_assets WHERE organization_id = ? AND call_id = ? ORDER BY created_at").bind(call.organization_id, call.id).all();
    return rows.results;
  }
  const now = new Date().toISOString();
  const assets = assetBlueprints.map(([type, title, department, summary]) => ({ id: crypto.randomUUID(), callId: call.id, type, title, department, summary }));
  const nodes = nodeBlueprints(call.id, call.transcript_text);
  const edgePairs = [[0,1,"experiences"],[1,2,"causes"],[0,3,"raises"],[3,4,"masks"],[1,4,"amplifies"],[2,5,"motivates"],[4,5,"must_resolve"],[0,5,"owns"]];
  const statements = assets.map((asset) => env.DB.prepare("INSERT INTO revenue_assets VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)").bind(asset.id, call.organization_id, asset.callId, asset.type, asset.title, asset.department, "review_required", JSON.stringify({ summary: asset.summary, sourceCall: call.title, evidenceBacked: true, aiGenerated: true }), now));
  nodes.forEach((node) => statements.push(env.DB.prepare("INSERT INTO knowledge_nodes VALUES (?, ?, ?, ?, ?, ?, ?, ?)").bind(node.id, call.organization_id, node.callId, node.type, node.label, node.confidence, node.evidence, now)));
  edgePairs.forEach(([source, target, relation]) => statements.push(env.DB.prepare("INSERT INTO knowledge_edges VALUES (?, ?, ?, ?, ?, ?, ?)").bind(crypto.randomUUID(), call.organization_id, call.id, nodes[source].id, nodes[target].id, relation, now)));
  statements.push(env.DB.prepare("UPDATE revenue_calls SET status = 'ready' WHERE organization_id = ? AND id = ?").bind(call.organization_id, call.id));
  await env.DB.batch(statements);
  return assets.map((asset) => ({ ...asset, status: "review_required", content_json: JSON.stringify({ summary: asset.summary, evidenceBacked: true, aiGenerated: true }) }));
}

export async function handleRevenueOSApi(request, env, url) {
  const organizationId = resolveOrganizationId(env);
  const ready = await ensureRevenueOS(env, organizationId);
  if (!ready) return response({ code: "storage_unavailable" }, 503);
  if (url.pathname === "/api/revenue-os/dashboard" && request.method === "GET") {
    const [calls, assets, approvedAssets, nodes, signals, readinessAssets, recentCalls, consentedCalls] = await Promise.all([
      env.DB.prepare("SELECT COUNT(*) count FROM revenue_calls WHERE organization_id = ?").bind(organizationId).first(),
      env.DB.prepare("SELECT COUNT(*) count FROM revenue_assets WHERE organization_id = ?").bind(organizationId).first(),
      env.DB.prepare("SELECT COUNT(*) count FROM revenue_assets WHERE organization_id = ? AND status = 'approved'").bind(organizationId).first(),
      env.DB.prepare("SELECT COUNT(*) count FROM knowledge_nodes WHERE organization_id = ?").bind(organizationId).first(),
      env.DB.prepare("SELECT * FROM intelligence_signals WHERE organization_id = ? AND status = 'open' ORDER BY created_at DESC").bind(organizationId).all(),
      env.DB.prepare("SELECT COUNT(*) count FROM revenue_assets WHERE organization_id = ? AND status = 'approved' AND asset_type IN ('roleplay','manager_coaching','rep_scorecard')").bind(organizationId).first(),
      env.DB.prepare("SELECT COUNT(*) count FROM revenue_calls WHERE organization_id = ? AND created_at >= datetime('now', '-90 days')").bind(organizationId).first(),
      env.DB.prepare("SELECT COUNT(*) count FROM revenue_calls WHERE organization_id = ? AND consent_status = 'confirmed'").bind(organizationId).first(),
    ]);
    const callCount = Number(calls?.count || 0); const assetCount = Number(assets?.count || 0); const approvedAssetCount = Number(approvedAssets?.count || 0); const nodeCount = Number(nodes?.count || 0);
    const revenueDna = calculateRevenueDna({ callCount, assetCount, approvedAssetCount, nodeCount, signals: signals.results, approvedReadinessAssetCount: Number(readinessAssets?.count || 0), recentCallCount: Number(recentCalls?.count || 0), consentedCallCount: Number(consentedCalls?.count || 0) });
    return response({ callCount, assetCount, approvedAssetCount, reviewRequiredCount: assetCount - approvedAssetCount, nodeCount, revenueDna, revenueDnaScore: revenueDna.overall ?? "—", knowledgeCoverage: callCount ? Math.min(100, Math.round(nodeCount / (callCount * 6) * 100)) : 0, signals: signals.results, departments: [{ name: "Sales", assets: 6 }, { name: "Enablement", assets: 5 }, { name: "Marketing", assets: 3 }, { name: "Product", assets: 3 }, { name: "Customer Success", assets: 2 }, { name: "Leadership", assets: 1 }] });
  }
  if (url.pathname === "/api/revenue-os/calls" && request.method === "GET") {
    const rows = await env.DB.prepare("SELECT id, provider, title, account_name, duration_seconds, consent_status, status, created_at FROM revenue_calls WHERE organization_id = ? ORDER BY created_at DESC LIMIT 50").bind(organizationId).all();
    return response(rows.results);
  }
  if (url.pathname === "/api/revenue-os/calls" && request.method === "POST") {
    const body = await request.json(); const provider = String(body.provider || "upload").toLowerCase(); const transcript = String(body.transcript || "").trim();
    if (!providers.includes(provider) || transcript.length < 40 || transcript.length > 200000) return response({ code: "validation_failed", message: "Choose a source and provide at least 40 characters of transcript evidence." }, 400);
    if (String(body.consentStatus || "").toLowerCase() !== "confirmed") return response({ code: "consent_required", message: "Confirm that the call may be processed under your organization’s consent policy." }, 400);
    const idempotencyKey = String(request.headers.get("idempotency-key") || body.idempotencyKey || `ingest:${provider}:${body.title || "untitled"}:${body.accountName || "unknown"}:${transcript.length}`).slice(0, 120);
    const prior = await env.DB.prepare("SELECT id, provider, title, account_name, duration_seconds, consent_status, status, created_at FROM revenue_calls WHERE organization_id = ? AND idempotency_key = ?").bind(organizationId, idempotencyKey).first();
    if (prior) return response({ call: prior, assetCount: 20, idempotent: true });
    const call = { id: crypto.randomUUID(), organization_id: organizationId, provider, title: String(body.title || "Customer conversation").slice(0, 120), account_name: String(body.accountName || "Unknown account").slice(0, 120), duration_seconds: Math.max(0, Number(body.durationSeconds || 0)), consent_status: "confirmed", status: "processing", transcript_text: redact(transcript), idempotency_key: idempotencyKey, created_at: new Date().toISOString() };
    await env.DB.prepare("INSERT INTO revenue_calls VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)").bind(call.id, call.organization_id, call.provider, call.title, call.account_name, call.duration_seconds, call.consent_status, call.status, call.transcript_text, call.idempotency_key, call.created_at).run();
    const assets = await generateRevenueAssets(env, call);
    return response({ call: { id: call.id, provider: call.provider, title: call.title, account_name: call.account_name, duration_seconds: call.duration_seconds, consent_status: call.consent_status, status: "ready", created_at: call.created_at }, assetCount: assets.length }, 201);
  }
  const assetsMatch = url.pathname.match(/^\/api\/revenue-os\/calls\/([^/]+)\/assets$/);
  if (assetsMatch && request.method === "GET") {
    const rows = await env.DB.prepare("SELECT id, asset_type, title, department, status, content_json, created_at FROM revenue_assets WHERE organization_id = ? AND call_id = ? ORDER BY created_at").bind(organizationId, assetsMatch[1]).all();
    return response(rows.results.map((row) => ({ ...row, content: JSON.parse(row.content_json) })));
  }
  const assetMatch = url.pathname.match(/^\/api\/revenue-os\/assets\/([^/]+)$/);
  if (assetMatch && request.method === "GET") {
    const asset = await env.DB.prepare("SELECT a.id, a.call_id, a.asset_type, a.title, a.department, a.status, a.content_json, a.created_at, c.title source_call_title, c.account_name, c.provider, c.consent_status FROM revenue_assets a JOIN revenue_calls c ON c.id = a.call_id AND c.organization_id = a.organization_id WHERE a.organization_id = ? AND a.id = ?").bind(organizationId, assetMatch[1]).first();
    if (!asset) return response({ code: "not_found" }, 404);
    const [evidence, reviews] = await Promise.all([
      env.DB.prepare("SELECT id, node_type, label, confidence, evidence FROM knowledge_nodes WHERE organization_id = ? AND call_id = ? ORDER BY confidence DESC LIMIT 8").bind(organizationId, asset.call_id).all(),
      env.DB.prepare("SELECT decision, rationale, reviewer, created_at FROM asset_reviews WHERE organization_id = ? AND asset_id = ? ORDER BY created_at DESC LIMIT 10").bind(organizationId, asset.id).all(),
    ]);
    return response({ ...asset, content: JSON.parse(asset.content_json), content_json: undefined, evidence: evidence.results, reviews: reviews.results });
  }
  const reviewMatch = url.pathname.match(/^\/api\/revenue-os\/assets\/([^/]+)\/review$/);
  if (reviewMatch && request.method === "POST") {
    const body = await request.json(); const validation = validateAssetReview(body);
    if (!validation.ok) return response({ code: validation.code, message: validation.code === "rationale_required" ? "Explain why this asset needs changes or should be rejected." : "Choose a valid review decision." }, 400);
    const asset = await env.DB.prepare("SELECT id, status FROM revenue_assets WHERE organization_id = ? AND id = ?").bind(organizationId, reviewMatch[1]).first();
    if (!asset) return response({ code: "not_found" }, 404);
    const actor = resolveActor(request, env); const existing = await env.DB.prepare("SELECT id, decision, rationale, created_at FROM asset_reviews WHERE organization_id = ? AND asset_id = ? AND reviewer = ? AND decision = ? ORDER BY created_at DESC LIMIT 1").bind(organizationId, asset.id, actor, validation.decision).first();
    if (existing && asset.status === validation.decision) return response({ assetId: asset.id, status: asset.status, review: existing, idempotent: true });
    const id = crypto.randomUUID(); const now = new Date().toISOString();
    await env.DB.batch([
      env.DB.prepare("UPDATE revenue_assets SET status = ? WHERE organization_id = ? AND id = ?").bind(validation.decision, organizationId, asset.id),
      env.DB.prepare("INSERT INTO asset_reviews VALUES (?, ?, ?, ?, ?, ?, ?)").bind(id, organizationId, asset.id, actor, validation.decision, validation.rationale, now),
    ]);
    await auditRevenueAction(env, organizationId, actor, `asset_${validation.decision}`, "revenue_asset", asset.id, { rationaleProvided: Boolean(body.rationale) });
    return response({ assetId: asset.id, status: validation.decision, review: { id, decision: validation.decision, rationale: validation.rationale, reviewer: actor, created_at: now } });
  }
  if (url.pathname === "/api/revenue-os/connectors" && request.method === "GET") {
    const rows = await env.DB.prepare("SELECT provider, status, mode, scopes_json, last_synced_at, last_error, updated_at FROM connector_connections WHERE organization_id = ?").bind(organizationId).all();
    const connected = new Map(rows.results.map((row) => [row.provider, row]));
    const credentialKeys = { gong: "GONG_CLIENT_ID", chorus: "CHORUS_CLIENT_ID", zoom: "ZOOM_CLIENT_ID", teams: "MICROSOFT_CLIENT_ID", salesforce: "SALESFORCE_CLIENT_ID" };
    return response(connectorCatalog.map((connector) => { const saved = connected.get(connector.provider); return { ...connector, status: saved?.status || "available", mode: saved?.mode || "not_configured", lastSyncedAt: saved?.last_synced_at || null, lastError: saved?.last_error || null, credentialsConfigured: connector.provider === "upload" || Boolean(env[credentialKeys[connector.provider]]) }; }));
  }
  const connectorSyncMatch = url.pathname.match(/^\/api\/revenue-os\/connectors\/([^/]+)\/sync$/);
  if (connectorSyncMatch && request.method === "POST") {
    const connector = connectorCatalog.find((item) => item.provider === connectorSyncMatch[1]);
    if (!connector) return response({ code: "not_found" }, 404);
    const credentialKeys = { gong: "GONG_CLIENT_ID", chorus: "CHORUS_CLIENT_ID", zoom: "ZOOM_CLIENT_ID", teams: "MICROSOFT_CLIENT_ID", salesforce: "SALESFORCE_CLIENT_ID" };
    const credentialsConfigured = connector.provider === "upload" || Boolean(env[credentialKeys[connector.provider]]); const now = new Date().toISOString(); const actor = resolveActor(request, env);
    const status = credentialsConfigured ? "connected" : "pilot_connected"; const mode = connector.provider === "upload" ? "native" : credentialsConfigured ? "oauth" : "manual_pilot";
    await env.DB.prepare("INSERT INTO connector_connections (id, organization_id, provider, status, mode, scopes_json, last_synced_at, last_error, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT(organization_id, provider) DO UPDATE SET status = excluded.status, mode = excluded.mode, scopes_json = excluded.scopes_json, last_synced_at = excluded.last_synced_at, last_error = NULL, updated_at = excluded.updated_at").bind(crypto.randomUUID(), organizationId, connector.provider, status, mode, JSON.stringify(connector.scopes), now, null, now, now).run();
    await auditRevenueAction(env, organizationId, actor, "connector_sync_verified", "connector", connector.provider, { mode, credentialsConfigured });
    return response({ provider: connector.provider, status, mode, lastSyncedAt: now, importedCalls: 0, message: credentialsConfigured ? "Connection verified. New permitted calls will sync automatically." : "Pilot sync verified. Add OAuth credentials before production backfill." });
  }
  if (url.pathname === "/api/revenue-os/advisor/actions" && request.method === "GET") {
    const rows = await env.DB.prepare("SELECT id, signal_id, action_type, title, owner_department, status, requested_by, result_json, completed_at, created_at FROM advisor_actions WHERE organization_id = ? ORDER BY created_at DESC LIMIT 50").bind(organizationId).all();
    return response(rows.results.map((row) => ({ ...row, result: JSON.parse(row.result_json), result_json: undefined })));
  }
  if (url.pathname === "/api/revenue-os/advisor/actions" && request.method === "POST") {
    const body = await request.json(); const actionType = String(body.actionType || "");
    const actionCatalog = {
      launch_drift_correction: { title: "Correct CRM replacement drift", department: "Enablement", steps: ["Draft corrected talk track", "Route to enablement owner", "Prepare targeted rep drill"] },
      generate_security_content: { title: "Create enterprise security messaging", department: "Marketing", steps: ["Draft evidence-backed security talk track", "Request Legal review", "Prepare battle-card update"] },
      route_product_signal: { title: "Route administrative-burden signal", department: "Product", steps: ["Bundle supporting evidence", "Notify product operations", "Add to next discovery review"] },
    };
    const definition = actionCatalog[actionType];
    if (!definition) return response({ code: "validation_failed", message: "Choose a supported advisor action." }, 400);
    const actor = resolveActor(request, env); const id = crypto.randomUUID(); const now = new Date().toISOString(); const signalId = body.signalId ? String(body.signalId).slice(0, 120) : null;
    if (signalId) { const signal = await env.DB.prepare("SELECT id FROM intelligence_signals WHERE organization_id = ? AND id = ?").bind(organizationId, signalId).first(); if (!signal) return response({ code: "not_found" }, 404); }
    const result = { steps: definition.steps, humanApprovalRequired: true, externalSideEffects: false };
    await env.DB.prepare("INSERT INTO advisor_actions VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)").bind(id, organizationId, signalId, actionType, definition.title, definition.department, "queued_for_review", actor, JSON.stringify(result), null, now).run();
    await auditRevenueAction(env, organizationId, actor, "advisor_action_queued", "advisor_action", id, { actionType, department: definition.department });
    return response({ id, actionType, title: definition.title, ownerDepartment: definition.department, status: "queued_for_review", result }, 202);
  }
  if (url.pathname === "/api/revenue-os/graph" && request.method === "GET") {
    const [nodes, edges] = await Promise.all([env.DB.prepare("SELECT * FROM knowledge_nodes WHERE organization_id = ? ORDER BY created_at DESC LIMIT 100").bind(organizationId).all(), env.DB.prepare("SELECT * FROM knowledge_edges WHERE organization_id = ? ORDER BY created_at DESC LIMIT 150").bind(organizationId).all()]);
    return response({ nodes: nodes.results, edges: edges.results });
  }
  if (url.pathname === "/api/revenue-os/deletions" && request.method === "GET") {
    const rows = await env.DB.prepare("SELECT id, scope, target_id, status, delete_after, completed_at, created_at FROM deletion_requests WHERE organization_id = ? ORDER BY created_at DESC LIMIT 50").bind(organizationId).all();
    return response(rows.results);
  }
  if (url.pathname === "/api/revenue-os/deletions" && request.method === "POST") {
    const body = await request.json(); const scope = String(body.scope || ""); const targetId = String(body.targetId || "").slice(0, 120);
    if (!['call','user','organization'].includes(scope) || !targetId) return response({ code: "validation_failed", message: "Choose a deletion scope and target." }, 400);
    const now = new Date(); const deleteAfter = new Date(now.getTime() + 72 * 60 * 60 * 1000); const id = crypto.randomUUID();
    const actor = resolveActor(request, env);
    await env.DB.prepare("INSERT INTO deletion_requests VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)").bind(id, organizationId, actor, scope, targetId, "queued", deleteAfter.toISOString(), null, now.toISOString()).run();
    await auditRevenueAction(env, organizationId, actor, "deletion_requested", "deletion_request", id, { scope, targetId });
    return response({ id, scope, targetId, status: "queued", deleteAfter: deleteAfter.toISOString() }, 202);
  }
  if (url.pathname === "/api/revenue-os/audit" && request.method === "GET") {
    const rows = await env.DB.prepare("SELECT id, actor, action, entity_type, entity_id, metadata_json, created_at FROM revenue_audit_events WHERE organization_id = ? ORDER BY created_at DESC LIMIT 100").bind(organizationId).all();
    return response(rows.results.map((row) => ({ ...row, metadata: JSON.parse(row.metadata_json), metadata_json: undefined })));
  }
  return response({ code: "not_found" }, 404);
}

