function repairCopy(value) {
  const replacements = [
    ["\u00c2\u00b7", "\u00b7"], ["\u00e2\u20ac\u2122", "\u2019"],
    ["\u00e2\u20ac\u0153", "\u201c"], ["\u00e2\u20ac\u009d", "\u201d"],
    ["\u00e2\u20ac\u201c", "\u2013"], ["\u00e2\u20ac\u201d", "\u2014"],
    ["\u00e2\u20ac\u00a6", "\u2026"], ["\u00e2\u2020\u2019", "\u2192"],
    ["\u00e2\u2020\u00a5", "\u21a5"], ["\u00e2\u2014\u017d", "\u25ce"],
    ["\u00e2\u2020\u2014", "\u2197"], ["\u00e2\u0153\u00a6", "\u2726"],
    ["\u00e2\u203a\u201c", "\u26d3"], ["\u00e2\u0153\u201c", "\u2713"],
    ["\u00e2\u0152\u201a", "\u2302"], ["\u00ce\u00a3", "\u03a3"],
    ["\u00ce\u201d", "\u0394"], ["\u00c3\u2014", "\u00d7"],
  ];
  return replacements.reduce((copy, [broken, fixed]) => copy.replaceAll(broken, fixed), value);
}

